# .enforcement.map: enforcement-coverage gates (run_enforcement_gates.sh, quota-aware-verified-swarm
# skill, references/enforcement_gates.md). Register: docs/security/TRUST_FINDINGS.md.
# kind     id        keys

# --- No silent skips ------------------------------------------------------------------------------
skips      K-1       path=tests/*.rs
suite      S-DOCKER  test=docker_acceptance_gate::docker_acceptance_gate needs=docker

# --- Artifact provenance (A-DOCKER: the gate copies from the build directory; convert before item 7)
artifact   A-DOCKER  script=scripts/docker_acceptance_gate.sh bin=parvault suite=docker_acceptance_gate::docker_acceptance_gate
open       A-DOCKER  expect=artifact by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md

# --- Completeness ---------------------------------------------------------------------------------
enum       E-WIRE    sym=src/network/behaviour.rs::MeshWireRequest
open       E-WIRE    expect=completeness by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md
adr        D-ADR     path=docs/adr/*.md
open       D-ADR     expect=completeness by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md

# --- Reach: checks that exist but are not called on the wire path ----------------------------------
reach      F-03      sym=src/network/wire_handler.rs::admission_decision from=src/network/wire_handler.rs::handle_mesh_wire_request ref=docs/security/TRUST_FINDINGS.md
reach      F-05      sym=src/network/wot.rs::verify_and_admit_public_ticket from=src/network/wire_handler.rs::handle_mesh_wire_request ref=docs/security/TRUST_FINDINGS.md
reach      F-06      sym=src/por/verifier.rs::verify_audit_response from=src/cli/daemon.rs::run_daemon ref=docs/security/TRUST_FINDINGS.md
open       F-06      expect=reach by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md
reach      F-15      sym=src/bootstrap.rs::verify_weather_quorum from=src/bin/parvault-seed.rs::run_seed_listener_loop ref=docs/security/TRUST_FINDINGS.md
open       F-15      expect=reach by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md

# --- Blocking calls on handler paths --------------------------------------------------------------
no-blocking F-18     path=src/network/wire_handler.rs
open       F-18      expect=no-blocking by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md
no-blocking B-DISC   path=src/network/discovery.rs
open       B-DISC    expect=no-blocking by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md

# --- ADR cross-references (existence only; F-16's keyword table is curated in its own item) --------
xref       X-ADR     path=src/**.rs pattern=ADR-(\d+) target=docs/adr/ADR-{}-*.md
xref       X-ADR-DOC path=docs/**.md pattern=ADR-(\d+) target=docs/adr/ADR-{}-*.md

# --- Formal proofs (P-01 to P-05; mutants are authored by QA) --------------------------------------
tla-spec   T-SPECS   path=specs/*.tla
open       T-SPECS   expect=tla-lint by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md
open       T-SPECS   expect=completeness by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md
module     P-01      path=src/network/wot.rs pattern=^(verify_and_admit_|is_peer_|apply_slashing_|slash_|record_failure) kani=required
open       P-01      expect=completeness by=v0.5.0 ref=docs/security/TRUST_FINDINGS.md

# --- Claims ----------------------------------------------------------------------------------------
claim      F-02a     sym=src/por/verifier.rs::grant_registration_decision accept=trust_enforcement::f02a_owner_grant_update_registered reject=trust_enforcement::f02a_foreign_grant_not_registered code=reject.repair_grant_owner_conflict bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-04-repair-grant-ciphertext-reconstruction.md
claim      F-02b     sym=src/por/verifier.rs::repair_read_decision accept=trust_enforcement::f02b_registered_grant_repair_read reject=trust_enforcement::f02b_foreign_grant_repair_read_refused code=reject.repair_grant_unregistered bin=parvault ref=docs/security/TRUST_FINDINGS.md covers=MeshWireRequest::GetCiphertextShard
claim      F-03      sym=src/network/wire_handler.rs::admission_decision accept=trust_enforcement::f03_admitted_put_shard_stored_daemon reject=trust_enforcement::f03_unadmitted_put_shard_refused_daemon code=reject.peer_not_admitted bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-05-recursive-wot-and-subtree-slashing.md covers=MeshWireRequest::PutShard
claim      F-03-SEED sym=src/network/wire_handler.rs::admission_decision accept=trust_enforcement::f03_admitted_put_shard_stored_seed reject=trust_enforcement::f03_unadmitted_put_shard_refused_seed code=reject.peer_not_admitted bin=parvault-seed ref=docs/security/TRUST_FINDINGS.md covers=MeshWireRequest::PutShard
claim      F-04      sym=src/network/wire_handler.rs::shard_owner_decision accept=trust_enforcement::f04_owner_claim_of_sender_stored reject=trust_enforcement::f04_invented_owner_claim_refused code=reject.owner_not_sender bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-15-elastic-bootstrap-and-earned-tiers.md
claim      F-05      sym=src/network/wot.rs::public_ticket_decision accept=trust_enforcement::f05_public_ticket_at_required_bits_admits reject=trust_enforcement::f05_public_ticket_one_bit_short_refused code=reject.ticket_insufficient_pow bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-24-public-commons-pow-swarm-mode.md covers=MeshWireRequest::AdmitPublicTicket
claim      F-10a     sym=src/network/client.rs::dht_candidate_decision accept=trust_enforcement::f10a_owner_catalog_recovered reject=trust_enforcement::f10a_squatted_catalog_ignored code=reject.dht_owner_mismatch bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-02-dht-encrypted-manifests.md covers=MeshWireRequest::GetDhtEnvelope
claim      F-10b     sym=src/network/server_events.rs::kad_record_decision accept=trust_enforcement::f10b_signed_envelope_record_stored reject=trust_enforcement::f10b_unsigned_record_refused code=reject.dht_record_invalid bin=parvault ref=docs/security/TRUST_FINDINGS.md
claim      F-21      sym=src/network/wot.rs::chain_leaf_decision accept=trust_enforcement::f21_handshake_own_chain_accepted reject=trust_enforcement::f21_handshake_chain_leaf_not_sender_refused code=reject.chain_leaf_not_sender bin=parvault ref=docs/security/TRUST_FINDINGS.md covers=MeshWireRequest::HandshakeWoT
claim      F-24      sym=src/network/wire_handler.rs::admission_decision accept=trust_enforcement::f24_admitted_blinded_put_stored reject=trust_enforcement::f24_unadmitted_blinded_put_refused code=reject.peer_not_admitted bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-11-four-layer-shard-anonymization.md covers=MeshWireRequest::PutBlindedShard
claim      F-24-ONION sym=src/network/wire_handler.rs::admission_decision accept=trust_enforcement::f24_admitted_onion_final_delivered reject=trust_enforcement::f24_unadmitted_onion_final_refused code=reject.peer_not_admitted bin=parvault ref=docs/security/TRUST_FINDINGS.md covers=MeshWireRequest::RelayPqOnionEnvelope
claim      F-25      sym=src/network/wire_handler.rs::device_cert_decision accept=trust_enforcement::f25_device_cert_of_sender_accepted reject=trust_enforcement::f25_device_cert_replayed_by_other_key_refused code=reject.device_cert_not_sender bin=parvault-seed ref=docs/security/TRUST_FINDINGS.md covers=MeshWireRequest::SyndicateLiteStripe
claim      F-25-DHT  sym=src/network/wire_handler.rs::admission_decision accept=trust_enforcement::f25_admitted_dht_put_stored reject=trust_enforcement::f25_unadmitted_dht_put_refused code=reject.peer_not_admitted bin=parvault ref=docs/security/TRUST_FINDINGS.md adr=docs/adr/ADR-02-dht-encrypted-manifests.md covers=MeshWireRequest::PutDhtEnvelope
# Each 2b fix adds its claim line (a differential pair rewritten from its reproduction in
# tests/trust_enforcement.rs) in the same commit. A claim cannot be declared before its check
# function exists (an unknown sym is an error even under expect=claim-missing).
# Findings with no line yet (no check function exists to name): F-07, F-08, F-09, F-12, F-17
#   (2c); F-22, F-23, F-26 (2c); F-24 issuer policy (2c).

ratchet    R         open=10 waive=0
